//! The built-in default skin, generated by `tools/skingen` into `assets/default-skin`.

use crate::container::{ContainerKind, SkinFiles};
use crate::skin::Skin;

macro_rules! embed {
    ($($name:literal),* $(,)?) => {
        &[$(($name, include_bytes!(concat!("../../../assets/default-skin/", $name)))),*]
    };
}

/// File names and contents of the built-in skin.
pub const FILES: &[(&str, &[u8])] = embed![
    "main.bmp",
    "titlebar.bmp",
    "cbuttons.bmp",
    "playpaus.bmp",
    "monoster.bmp",
    "shufrep.bmp",
    "numbers.bmp",
    "volume.bmp",
    "balance.bmp",
    "posbar.bmp",
    "text.bmp",
    "eqmain.bmp",
    "eqmain_iso.bmp",
    "eq_ex.bmp",
    "pledit.bmp",
    "gen.bmp",
    "genex.bmp",
    "video.bmp",
    "mb.bmp",
    "pledit.txt",
    "viscolor.txt",
    "readme.txt",
];

/// The built-in skin's files.
pub fn files() -> SkinFiles {
    SkinFiles::from_entries(
        ContainerKind::BuiltIn,
        FILES.iter().map(|(n, d)| (n.to_string(), d.to_vec())),
    )
}

/// The built-in skin, loaded.
pub fn skin() -> Skin {
    Skin::builtin(&files())
}
